namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GemmGroupNormMinBiasAddCustomTilingData tiling;

    const gert::Shape* in_shape = context->GetInputShape(0);
    auto ori = in_shape->GetOriginShape();
    std::vector<int64_t> dims = ori.GetDims();
    uint32_t n = 1, c = 1, h = 1, w = 1;
    if (dims.size() == 2) {
        n = static_cast<uint32_t>(dims[0]);
        c = static_cast<uint32_t>(dims[1]);
    } else if (dims.size() == 4) {
        n = static_cast<uint32_t>(dims[0]);
        c = static_cast<uint32_t>(dims[1]);
        h = static_cast<uint32_t>(dims[2]);
        w = static_cast<uint32_t>(dims[3]);
    } else {
        uint64_t sz = ori.GetShapeSize();
        c = static_cast<uint32_t>(sz);
        n = 1;
    }

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_totalLength(n * c * h * w);
    tiling.set_tileNum(TILE_NUM);
    // Workspace for ReduceMin intermediate buffer, see ReduceMin example: minimum 32 elements (128B for float)
    tiling.set_reduceWorkSize(32);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    context->SetTilingKey(1);
    return ge::GRAPH_SUCCESS;
}
}

